const body = $json.body || $json;
const owner = body.owner || {};
const property = body.property || body;
const first = String(owner.first_name || body.first_name || '').trim();
const last = String(owner.last_name || body.last_name || '').trim();
const address = String(property.address || property.property_address || '').trim();
if (!first || !last || !address) throw new Error('owner first_name, last_name and property address are required');
const distress = Array.isArray(property.distress_markers) ? property.distress_markers : [];
return [{ json: { first_name: first, last_name: last, phone: owner.phone || body.phone || null, email: owner.email || body.email || null, source: body.source || 'batchdata', notes: body.notes || null, property_address: address, property_city: property.city || property.property_city || null, property_state: String(property.state || property.property_state || 'NC').toUpperCase(), property_zip: property.zip_code || property.zip || property.property_zip || null, property_type: property.property_type || null, external_id: body.external_id || property.external_id || null, distress_markers: distress, estimated_value: property.estimated_value || property.market_value || null, asking_price: property.asking_price || null, condition: property.condition || null, source_payload_version: '1' } }];
